void generateSalesReport(vector<Invoice> invoices, Vehicle vehicles[], int numVehicles, vector<Vehicle> soldVehicles) {
    // Generate report header
    cout << "---------------------- SALES REPORT ----------------------" << endl;
    cout << "Total vehicles sold: " << numVehiclesSold(vehicles, numVehicles) << endl;
    // Rest of the function code
}

int numVehiclesSold(Vehicle vehicles[], int numVehicles) {
    int count = 0;
    // Loop through all the vehicles
    for (int i = 0; i < numVehicles; i++) {
        // Check if the vehicle has been sold
        if (!vehicles[i].saleDates.empty()) {
            // Increment the count of sold vehicles
            count++;
        }
    }
    return count;
}

